          id="expense-amount"
          type="number"
          step="0.01"
          value={amount}
          onChange={(event) => setAmount(event.target.value)}
          aria-invalid={Boolean(errors.amount)}
          aria-describedby={errors.amount ? 'expense-amount-error' : undefined}
